    agam_float vy_hat = vy / (1.0 - pow(beta2, t_f));

    x -= learning_rate * mx_hat / (sqrt(vx_hat) + epsilon);
    y -= learning_rate * my_hat / (sqrt(vy_hat) + epsilon);
